/**
 * מיקרו-אינטראקציות של מצביע (עכבר בלבד — finePointer):
 *  - סמן מותאם: נקודה מדויקת + טבעת עם השהיה; גדלה על קישורים, מציגה תווית על [data-cursor="…"].
 *  - מגנטיות: [data-magnetic] נמשך לעבר המצביע (עד 10px) וחוזר בקפיץ.
 *  - הטיה תלת-ממדית: [data-tilt] נוטה עד 7° לפי המצביע + הילת זהב שעוקבת (--mx/--my).
 * תפקיד (REDESIGN-PLAN §6.2): משוב — "הדבר הזה חי ומגיב לי".
 */
import { gsap, finePointer, reduced } from './core';

export function initCursor() {
  if (!finePointer() || reduced()) return;
  const root = document.documentElement;
  const dot = document.createElement('div'); dot.className = 'cur-dot';
  const ring = document.createElement('div'); ring.className = 'cur-ring';
  const label = document.createElement('span'); label.className = 'cur-label'; ring.appendChild(label);
  dot.setAttribute('aria-hidden', 'true'); ring.setAttribute('aria-hidden', 'true');
  document.body.append(ring, dot);
  root.classList.add('has-cursor');

  const setDot = { x: gsap.quickSetter(dot, 'x', 'px'), y: gsap.quickSetter(dot, 'y', 'px') };
  const ringX = gsap.quickTo(ring, 'x', { duration: 0.45, ease: 'power3.out' });
  const ringY = gsap.quickTo(ring, 'y', { duration: 0.45, ease: 'power3.out' });
  let shown = false;
  addEventListener('pointermove', (e) => {
    if (e.pointerType !== 'mouse') return;
    setDot.x(e.clientX); setDot.y(e.clientY); ringX(e.clientX); ringY(e.clientY);
    if (!shown) { shown = true; root.classList.add('cur-shown'); }
    const t = e.target as HTMLElement;
    const lab = t.closest<HTMLElement>('[data-cursor]');
    const text = t.closest('input, textarea, select, [contenteditable]');
    const link = t.closest('a, button, [role="button"], label, summary');
    ring.dataset.state = text ? 'text' : lab ? 'label' : link ? 'link' : '';
    label.textContent = lab?.dataset.cursor ?? '';
  }, { passive: true });
  document.addEventListener('pointerleave', () => { shown = false; root.classList.remove('cur-shown'); });
  addEventListener('pointerdown', () => ring.classList.add('down'));
  addEventListener('pointerup', () => ring.classList.remove('down'));
}

export function initMagnetic(root: ParentNode = document) {
  if (!finePointer() || reduced()) return;
  root.querySelectorAll<HTMLElement>('[data-magnetic]').forEach((el) => {
    const strength = Number(el.dataset.magnetic) || 0.28;
    const xTo = gsap.quickTo(el, 'x', { duration: 0.5, ease: 'power3.out' });
    const yTo = gsap.quickTo(el, 'y', { duration: 0.5, ease: 'power3.out' });
    el.addEventListener('pointermove', (e) => {
      const r = el.getBoundingClientRect();
      const dx = e.clientX - (r.left + r.width / 2), dy = e.clientY - (r.top + r.height / 2);
      xTo(gsap.utils.clamp(-10, 10, dx * strength)); yTo(gsap.utils.clamp(-10, 10, dy * strength));
    });
    el.addEventListener('pointerleave', () => {
      gsap.to(el, { x: 0, y: 0, duration: 0.9, ease: 'elastic.out(1, 0.45)' });
    });
  });
}

export function initTilt(root: ParentNode = document) {
  if (!finePointer() || reduced()) return;
  root.querySelectorAll<HTMLElement>('[data-tilt]').forEach((el) => {
    const max = Number(el.dataset.tilt) || 7;
    gsap.set(el, { transformPerspective: 900 });
    const rx = gsap.quickTo(el, 'rotationX', { duration: 0.6, ease: 'power3.out' });
    const ry = gsap.quickTo(el, 'rotationY', { duration: 0.6, ease: 'power3.out' });
    el.addEventListener('pointermove', (e) => {
      const r = el.getBoundingClientRect();
      const px = (e.clientX - r.left) / r.width, py = (e.clientY - r.top) / r.height;
      ry((px - 0.5) * 2 * max); rx(-(py - 0.5) * 2 * max);
      el.style.setProperty('--mx', `${(px * 100).toFixed(1)}%`);
      el.style.setProperty('--my', `${(py * 100).toFixed(1)}%`);
      el.classList.add('tilting');
    });
    el.addEventListener('pointerleave', () => { rx(0); ry(0); el.classList.remove('tilting'); });
  });
}
