/**
 * ליבת התנועה (REDESIGN-PLAN §6, גרסה 2 — 2026-09-26).
 * GSAP + ScrollTrigger לסצנות גלילה מוצמדות/נגררות (עקבי בכל הדפדפנים, בניגוד ל-scroll-driven CSS),
 * גלילה מקורית בכל מקום (Lenis הוסר — ראו initSmooth).
 */
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

export { gsap, ScrollTrigger };

export const reduced = () =>
  matchMedia('(prefers-reduced-motion: reduce)').matches || document.documentElement.dataset.motion === 'reduced';
/** עכבר אמיתי (ריחוף + מצביע עדין) — רק שם יש סמן מותאם, מגנטיות והטיה */
export const finePointer = () => matchMedia('(hover: hover) and (pointer: fine)').matches;
export const isRTL = () => document.documentElement.dir === 'rtl';
/** "קדימה" בכיוון הקריאה: ‎-1 ב-RTL, ‎+1 ב-LTR */
export const fwd = () => (isRTL() ? -1 : 1);

/* Lenis הוסר (דוד 2026-09-26: "מהירות הגלילה של העכבר מול תנועת הרינדור — הכול צריך להיות הגיוני").
   גלילה חלקה-מלאכותית מאחרת את הדף אחרי היד; גלילה מקורית מגיבה 1:1 לגלגלת ולמשטח המגע, והבמה עוקבת אחריה. */
export function initSmooth() { return null; }

export function scrollToEl(el: Element) {
  el.scrollIntoView({ behavior: reduced() ? 'auto' : 'smooth', block: 'start' });
}
